with feeders as (
    select
        md5(upper('HUB_RISK_OBJECT|' || (HUB_RISK_OBJECT_BK__contract_id_first_name_middle_name_last_name_date_of_birth))) as HUB_RISK_OBJECT_HK
        , coalesce(nullif(trim(borrower_type), ''), '') as INTEREST_TYPE
        , cast(null as varchar) as INTEREST_HOLDER_REFERENCE
        , cast(null as varchar) as LOAN_TYPE
        , cast(null as varchar) as LOAN_AMOUNT
        , cast(null as varchar) as FINANCIER_NAME
        , 'BA_CCP_INSURED_DETAILS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ba_ccp_insured_details') }}
    where (md5(normalise(upper(nullif(coalesce(nullif(trim(contract_id),''),'') || '|INSURED|' || coalesce(nullif(trim(first_name),''),'') || '|' || coalesce(nullif(trim(middle_name),''),'') || '|' || coalesce(nullif(trim(last_name),''),'') || '|' || coalesce(nullif(trim(to_char(date_of_birth)),''),''), '|INSURED||||'))))) is not null
    union all
    select
        md5(upper('HUB_RISK_OBJECT|' || (HUB_RISK_OBJECT_BK__LOAN_ACC_NUMBER))) as HUB_RISK_OBJECT_HK
        , 'LOAN' as INTEREST_TYPE
        , coalesce(nullif(trim(BANK_NAME), ''), '') as INTEREST_HOLDER_REFERENCE
        , TYPE_LOAN as LOAN_TYPE
        , SANCTIONED_LOAN as LOAN_AMOUNT
        , BANK_NAME as FINANCIER_NAME
        , 'BA_CCP_SUB_MATER_DTLS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ba_ccp_sub_mater_dtls') }}
    where (nullif('LOANACC:' || nullif(trim(LOAN_ACC_NUMBER),''), 'LOANACC:')) is not null
),

resolved as (
    select
        HUB_RISK_OBJECT_HK,
        INTEREST_TYPE,
        INTEREST_HOLDER_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then LOAN_TYPE end) as LOAN_TYPE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then LOAN_AMOUNT end) as LOAN_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_delta3' then FINANCIER_NAME end) as FINANCIER_NAME,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_RISK_OBJECT_HK, INTEREST_TYPE, INTEREST_HOLDER_REFERENCE
),

hashed as (
    select
        *,
        case when INTEREST_TYPE is not null or INTEREST_HOLDER_REFERENCE is not null or LOAN_TYPE is not null or LOAN_AMOUNT is not null or FINANCIER_NAME is not null
                     then md5(upper(coalesce(cast(INTEREST_TYPE as varchar), '') || '|' || coalesce(cast(INTEREST_HOLDER_REFERENCE as varchar), '') || '|' || coalesce(cast(LOAN_TYPE as varchar), '') || '|' || coalesce(cast(LOAN_AMOUNT as varchar), '') || '|' || coalesce(cast(FINANCIER_NAME as varchar), '')))
                end as SAT_RISK_OBJECT_INSURABLE_INTEREST_HASHDIFF
    from resolved
)

select * from hashed
where HUB_RISK_OBJECT_HK is not null
  and SAT_RISK_OBJECT_INSURABLE_INTEREST_HASHDIFF is not null
